draw(rightanglemark(inters[2],inters[5],dir(210),4));
dot("$A$",dir(90),N);
dot("$C$",dir(210),W);
dot("$B$",dir(-30),E);
dot("$F$",inters[0],E);
dot("$E$",inters[2],W);
dot("$D$",inters[5],S);
